import{at as e,it as t,o as n,yt as r}from"./chunks/framework.B-d2E8F-.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}`),a={name:`guide/configuration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>TeXRA uses its own settings system across the VS Code extension, desktop app, and command-line interface. Configure TeXRA in its Dashboard or CLI settings view; TeXRA does not contribute product settings to VS Code&#39;s Settings editor.</p><h2 id="open-texra-settings" tabindex="-1">Open TeXRA settings <a class="header-anchor" href="#open-texra-settings" aria-label="Permalink to “Open TeXRA settings”">​</a></h2><ul><li><strong>VS Code extension:</strong> run <strong>TeXRA: Show Settings Dashboard</strong> from the Command Palette.</li><li><strong>Desktop app:</strong> open <strong>Settings</strong>.</li><li><strong>CLI:</strong> choose <strong>Settings</strong> in the launcher, run <code>texra config</code>, or enter <code>/config</code> during a chat.</li></ul><p>The Dashboard groups the current controls by subject:</p><ul><li><strong>Account</strong>: sign-in status, telemetry, and subscription access (ChatGPT, Grok, Kimi Code, GLM Coding Plan, and Copilot).</li><li><strong>Models</strong>: provider keys and model visibility.</li><li><strong>Agents</strong>: available agents, active teams, orchestration, and session reliability.</li><li><strong>Capabilities</strong>: tool availability, permissions, skills, connected coding agents, and LaTeX processing.</li><li><strong>Workspace</strong>: Git behavior and shortcuts.</li><li><strong>Data &amp; Activity</strong>: memory and autonomous goals (the <strong>Memory</strong> and <strong>Goals</strong> tabs).</li></ul><p>Settings that benefit from an ordinary control appear directly in these views. File-handling rules and other internal implementation constants are not exposed as configuration.</p><h2 id="where-settings-live" tabindex="-1">Where settings live <a class="header-anchor" href="#where-settings-live" aria-label="Permalink to “Where settings live”">​</a></h2><p>For an open project, all three hosts read:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;project&gt;/.texra/config.json</span></span></code></pre></div><p>User-wide values are stored in:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/.texra/global-storage/config.json</span></span></code></pre></div><p>Project values override user-wide values. Explicit command-line flags and environment variables override saved values when a command documents such an override. If a host cannot write the project directory, it uses an internal workspace store so that its settings view remains usable; that fallback is not shared with the other hosts.</p><p>New releases begin with the current defaults. TeXRA does not import old values from <code>.vscode/settings.json</code>.</p><p>The JSON files use flat <code>texra.*</code> keys. For example:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;texra.skills.enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;texra.telemetry.enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;texra.toolUse.requireEditApproval&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;texra.model.retry.maxAttempts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Prefer the settings views for ordinary changes: they validate values and place them at the intended project or user scope.</p><h2 id="model-access-and-credentials" tabindex="-1">Model access and credentials <a class="header-anchor" href="#model-access-and-credentials" aria-label="Permalink to “Model access and credentials”">​</a></h2><p>The <strong>Providers &amp; Models</strong> view is the single home for model access, provider API keys, provider behavior, model visibility, and retry settings. Account connections that stand in for a provider key live in the <strong>Account</strong> group, under <strong>Subscriptions</strong>: ChatGPT, Grok, Kimi Code, the GLM Coding Plan, and Copilot. TeXRA account sign-in also sits in that group, under <strong>Account &amp; Usage</strong>. It unlocks the hosted research-agent catalog and does not supply model access.</p><p>Saved provider keys currently use each host&#39;s secure credential mechanism. They are not copied through the shared JSON configuration. Environment-variable keys are available to any TeXRA host launched with that environment.</p><h2 id="skills-tools-and-privacy" tabindex="-1">Skills, tools, and privacy <a class="header-anchor" href="#skills-tools-and-privacy" aria-label="Permalink to “Skills, tools, and privacy”">​</a></h2><p>The <strong>Tools</strong> view contains the skills switch, tool availability, and approval controls. The CLI exposes the same skills switch from its launcher and settings view. Tools that are disabled globally are removed from an agent&#39;s available tool list even when its definition names them.</p><p>The <strong>Account &amp; Usage</strong> view contains the telemetry switch. The environment variables <code>TEXRA_NO_TELEMETRY=1</code> and <code>DO_NOT_TRACK=1</code> also disable telemetry.</p><h3 id="usage-logging" tabindex="-1">Usage logging <a class="header-anchor" href="#usage-logging" aria-label="Permalink to “Usage logging”">​</a></h3><p>When telemetry is enabled and you are signed in, TeXRA records model and provider names, agent category, token counts, cost, response time, route, stream identifier, version, and host. It does not send prompt text, document content, or file names. Turning telemetry off stops reporting for runs billed through your own provider key.</p><h2 id="file-discovery" tabindex="-1">File discovery <a class="header-anchor" href="#file-discovery" aria-label="Permalink to “File discovery”">​</a></h2><p>TeXRA uses built-in file extensions and exclusions when discovering inputs, context, edited files, and media. The former <code>texra.files.included.*</code> and <code>texra.files.ignored.*</code> settings have been removed. Saved values for those keys no longer affect discovery.</p><h2 id="latex-configuration" tabindex="-1">LaTeX configuration <a class="header-anchor" href="#latex-configuration" aria-label="Permalink to “LaTeX configuration”">​</a></h2><p>The <strong>LaTeX</strong> view contains the settings that remain useful to change:</p><ul><li>inline criticism display;</li><li>compile and diff behavior;</li><li>formatter selection; and</li><li>direct, regular-expression, and custom replacement rules.</li></ul><p>The latexdiff picture-environment pattern is a fixed product rule rather than a user setting.</p><p>Some rows recommend settings owned by VS Code or another extension, such as an Explorer exclusion. Those rows are explicitly labeled and are separate from TeXRA&#39;s native configuration.</p><h2 id="agent-execution-settings-webview-interface" tabindex="-1">Agent execution settings (webview interface) <a class="header-anchor" href="#agent-execution-settings-webview-interface" aria-label="Permalink to “Agent execution settings (webview interface)”">​</a></h2><p>Per-run controls in the task composer affect only the task being launched. They include attached files and optional context helpers such as TeX count. Persistent agent visibility and team selection belong in the Dashboard instead.</p><h2 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to “Debugging”">​</a></h2><p>Enable <strong>Save model I/O</strong> only while diagnosing a run. Its current key is:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;texra.debug.saveModelIO&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>It saves request messages, raw responses, and the final input prompt alongside the execution&#39;s debug artifacts. These files can contain sensitive material; turn the option off after the investigation.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ol><li>Open the relevant native settings view and confirm the displayed value.</li><li>Run <code>texra doctor</code> in a project to inspect the CLI&#39;s resolved configuration.</li><li>Check <code>&lt;project&gt;/.texra/config.json</code> for a project override.</li><li>Check <code>~/.texra/global-storage/config.json</code> for a user-wide value.</li><li>Remove a saved key to return that setting to its current default.</li></ol><p>For feature-specific guidance, read <a href="./models.html">Models</a>, <a href="./latex-tools.html">LaTeX tools</a>, <a href="./agent-integrations.html">Agent integrations</a>, and <a href="./memory.html">Memory</a>.</p>`,41)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};